class CartController {

    // KHÔNG nhận userId từ client (không có trong path/body) - Cart luôn gắn
    // với người dùng đang xác thực. Giống cơ chế đã thiết lập ở Day 24/33: ở
    // mỗi request đã xác thực bằng Bearer JWT, principal là một đối tượng Jwt
    // (KHÔNG phải UserDetails), id người dùng là claim sub đã nhúng vào JWT
    // lúc phát hành ở Day 33 - đọc qua
    // ((Jwt) authentication.getPrincipal()).getSubject(). TUYỆT ĐỐI không lấy
    // userId từ một trường do client tự gửi (path/body), vì client có thể giả
    // mạo giá trị đó để đọc/sửa giỏ hàng của người khác.
    @org.springframework.web.bind.annotation.GetMapping("/api/cart/items")
    java.util.List<CartItemDto> getItems(org.springframework.security.core.Authentication authentication) {
        Long currentUserId = Long.valueOf(
            ((org.springframework.security.oauth2.jwt.Jwt) authentication.getPrincipal()).getSubject());
        Cart cart = cartService.findOrCreateForUser(currentUserId);
        return cart.getItems();
    }
}

